import http from 'node:http';

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const info = {
    method: req.method,
    jalur: url.pathname,
    kategori: url.searchParams.get('kategori'),
    halaman: Number(url.searchParams.get('halaman') ?? 1),
    klien: req.headers['x-klien'] ?? 'tidak diketahui',
  };
  res.end(JSON.stringify(info));
});
server.listen(3000);

const cetak = (d) => console.log(d.method, d.jalur, d.kategori, d.halaman, d.klien);
let r = await fetch('http://localhost:3000/produk?kategori=minuman&halaman=2');
cetak(await r.json());
r = await fetch('http://localhost:3000/pesanan', { method: 'DELETE', headers: { 'X-Klien': 'aplikasi-kasir' } });
cetak(await r.json());
server.close();

