import http from 'node:http';
const menu = ['Kopi Susu', 'Teh Tarik', 'Es Kopi'];
const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const q = (url.searchParams.get('q') ?? '').toLowerCase();
  const cocok = menu.filter((m) => m.toLowerCase().includes(q));
  res.end(cocok.join(', '));
});
server.listen(3000);
const r = await fetch('http://localhost:3000/menu?q=KOPI');
console.log(await r.text());
server.close();

